import type { Metadata } from "next";
import { founders, services, site, type Service } from "./site";

/**
 * Per-page metadata: title, description, canonical URL and social-share tags, all from one call.
 * `path` is the page's route, e.g. "/about". Share images are generated by the opengraph-image files.
 */
export function pageMetadata({
  title,
  description,
  path,
  absoluteTitle = false,
  image = "/opengraph-image",
}: {
  title: string;
  description: string;
  path: string;
  /** Use the title as-is instead of appending " | GodMode AI Solutions". */
  absoluteTitle?: boolean;
  /** Share image route. Defaults to the site-wide one; service pages pass their own. */
  image?: string;
}): Metadata {
  const shareTitle = absoluteTitle ? title : `${title} | ${site.name}`;
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: site.name,
      locale: "en_NG",
      url: path,
      title: shareTitle,
      description,
      images: [{ url: image, width: 1200, height: 630, alt: shareTitle }],
    },
    twitter: { card: "summary_large_image", title: shareTitle, description, images: [image] },
  };
}

/* ------------------------------------------------------------------ */
/* Structured data (schema.org JSON-LD)                                */
/* ------------------------------------------------------------------ */

const abs = (path: string) => `${site.url}${path}`;
export const ORG_ID = `${site.url}/#organization`;

/** The business itself. Rendered on every page from the root layout. */
export function organizationSchema() {
  return {
    "@context": "https://schema.org",
    "@type": "ProfessionalService",
    "@id": ORG_ID,
    name: site.name,
    legalName: site.legalName,
    url: site.url,
    logo: abs("/brand/logo.png"),
    image: abs("/opengraph-image"),
    description: site.description,
    slogan: site.positioning,
    email: site.email,
    telephone: site.phones[0].tel,
    address: {
      "@type": "PostalAddress",
      addressLocality: "Lagos",
      addressRegion: "Lagos",
      addressCountry: "NG",
    },
    areaServed: { "@type": "Country", name: "Nigeria" },
    contactPoint: site.phones.map((p) => ({
      "@type": "ContactPoint",
      telephone: p.tel,
      contactType: "customer service",
      areaServed: "NG",
      availableLanguage: ["English"],
    })),
    founder: founders.map((f) => ({ "@type": "Person", name: f.name, jobTitle: f.role })),
    knowsAbout: [
      "Artificial intelligence",
      "AI transformation",
      "Workflow automation",
      "AI training",
      "Web development",
      "Software development",
      "Digital marketing",
      "Social media strategy",
    ],
    hasOfferCatalog: {
      "@type": "OfferCatalog",
      name: "Services",
      itemListElement: services.map((s) => ({
        "@type": "Offer",
        itemOffered: { "@type": "Service", name: s.title, url: abs(`/services/${s.slug}`) },
      })),
    },
    sameAs: site.socials.map((s) => s.url),
  };
}

export function websiteSchema() {
  return {
    "@context": "https://schema.org",
    "@type": "WebSite",
    "@id": `${site.url}/#website`,
    name: site.name,
    url: site.url,
    inLanguage: "en-NG",
    publisher: { "@id": ORG_ID },
  };
}

/** Breadcrumb trail. Home is added automatically. */
export function breadcrumbSchema(items: { name: string; path: string }[]) {
  const trail = [{ name: "Home", path: "/" }, ...items];
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: trail.map((item, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: item.name,
      item: abs(item.path === "/" ? "" : item.path) || site.url,
    })),
  };
}

export function serviceSchema(s: Service) {
  return {
    "@context": "https://schema.org",
    "@type": "Service",
    "@id": abs(`/services/${s.slug}#service`),
    name: s.title,
    serviceType: s.shortTitle,
    description: s.summary,
    url: abs(`/services/${s.slug}`),
    provider: { "@id": ORG_ID },
    areaServed: { "@type": "Country", name: "Nigeria" },
    hasOfferCatalog: {
      "@type": "OfferCatalog",
      name: s.title,
      itemListElement: s.outcomes.map((o) => ({
        "@type": "Offer",
        itemOffered: { "@type": "Service", name: o.title, description: o.description },
      })),
    },
  };
}

export function faqSchema(faqs: { q: string; a: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: faqs.map((f) => ({
      "@type": "Question",
      name: f.q,
      acceptedAnswer: { "@type": "Answer", text: f.a },
    })),
  };
}
